-- CI-only schema fixture for public social content; never applied to Supabase.
CREATE TABLE IF NOT EXISTS public.posts(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,author_id uuid,author_name text NOT NULL DEFAULT 'مستخدم',content text NOT NULL DEFAULT '',post_type text NOT NULL DEFAULT 'عام',image_url text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.posts ENABLE ROW LEVEL SECURITY;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.posts TO authenticated,anon;
GRANT USAGE,SELECT ON SEQUENCE public.posts_id_seq TO authenticated;
CREATE POLICY posts_select_public ON public.posts FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY posts_insert_own ON public.posts FOR INSERT TO authenticated WITH CHECK(author_id=(SELECT auth.uid()));
CREATE POLICY posts_update_own ON public.posts FOR UPDATE TO authenticated USING(author_id=(SELECT auth.uid())) WITH CHECK(author_id=(SELECT auth.uid()));
CREATE POLICY posts_delete_own ON public.posts FOR DELETE TO authenticated USING(author_id=(SELECT auth.uid()));

CREATE TABLE IF NOT EXISTS public.reels(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,author_id uuid,title text NOT NULL DEFAULT 'ريلز جديد',author_name text NOT NULL DEFAULT 'مستخدم',media_url text,likes_count bigint NOT NULL DEFAULT 0,comments_count bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.reels ENABLE ROW LEVEL SECURITY;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.reels TO authenticated,anon;
GRANT USAGE,SELECT ON SEQUENCE public.reels_id_seq TO authenticated;
CREATE POLICY reels_select_public ON public.reels FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY reels_insert_own ON public.reels FOR INSERT TO authenticated WITH CHECK(author_id=(SELECT auth.uid()));
CREATE POLICY reels_update_own ON public.reels FOR UPDATE TO authenticated USING(author_id=(SELECT auth.uid())) WITH CHECK(author_id=(SELECT auth.uid()));
CREATE POLICY reels_delete_own ON public.reels FOR DELETE TO authenticated USING(author_id=(SELECT auth.uid()));

CREATE TABLE IF NOT EXISTS public.comments(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,target_id text NOT NULL,target_type text NOT NULL DEFAULT 'post',user_id uuid NOT NULL,author_name text NOT NULL DEFAULT 'مستخدم',content text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.comments ENABLE ROW LEVEL SECURITY;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.comments TO authenticated,anon;
GRANT USAGE,SELECT ON SEQUENCE public.comments_id_seq TO authenticated;
CREATE POLICY comments_select_public ON public.comments FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY comments_insert_own ON public.comments FOR INSERT TO authenticated WITH CHECK(user_id=(SELECT auth.uid()));
CREATE POLICY comments_update_own ON public.comments FOR UPDATE TO authenticated USING(user_id=(SELECT auth.uid())) WITH CHECK(user_id=(SELECT auth.uid()));
CREATE POLICY comments_delete_own ON public.comments FOR DELETE TO authenticated USING(user_id=(SELECT auth.uid()));

CREATE TABLE IF NOT EXISTS public.follows(follower_id uuid NOT NULL,following_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT follows_pair_unique UNIQUE(follower_id,following_id));
ALTER TABLE public.follows ENABLE ROW LEVEL SECURITY;
GRANT SELECT,INSERT,DELETE ON public.follows TO authenticated;
CREATE POLICY follows_select_participating ON public.follows FOR SELECT TO authenticated USING(follower_id=(SELECT auth.uid()) OR following_id=(SELECT auth.uid()));
CREATE POLICY follows_insert_self ON public.follows FOR INSERT TO authenticated WITH CHECK(follower_id=(SELECT auth.uid()) AND follower_id<>following_id);
CREATE POLICY follows_delete_self ON public.follows FOR DELETE TO authenticated USING(follower_id=(SELECT auth.uid()));

CREATE TABLE IF NOT EXISTS public.post_likes(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,post_id bigint NOT NULL,user_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT post_likes_unique UNIQUE(post_id,user_id));
ALTER TABLE public.post_likes ENABLE ROW LEVEL SECURITY;
GRANT SELECT,INSERT,DELETE ON public.post_likes TO authenticated;
GRANT USAGE,SELECT ON SEQUENCE public.post_likes_id_seq TO authenticated;
CREATE POLICY post_likes_select_own ON public.post_likes FOR SELECT TO authenticated USING(user_id=(SELECT auth.uid()));
CREATE POLICY post_likes_insert_own ON public.post_likes FOR INSERT TO authenticated WITH CHECK(user_id=(SELECT auth.uid()));
CREATE POLICY post_likes_delete_own ON public.post_likes FOR DELETE TO authenticated USING(user_id=(SELECT auth.uid()));

CREATE TABLE IF NOT EXISTS public.reel_likes(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,reel_id bigint NOT NULL,user_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT reel_likes_unique UNIQUE(reel_id,user_id));
ALTER TABLE public.reel_likes ENABLE ROW LEVEL SECURITY;
