CREATE POLICY reel_likes_insert_own ON public.reel_likes FOR INSERT TO authenticated WITH CHECK(user_id=(SELECT auth.uid()));
CREATE POLICY reel_likes_delete_own ON public.reel_likes FOR DELETE TO authenticated USING(user_id=(SELECT auth.uid()));
